<style>/* 主容器 */
.monitoring-dashboard {
  max-width: 1600px;
  margin: 0 auto;
  padding: 20px;
  background: #f1f5f9;
  min-height: 100vh;
  transition: all 0.3s ease;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
