  margin-bottom: 8px;
  display: flex;
  gap: 12px;
  background: #f8fafc;
}

.dark-mode .alert-item {
  background: #334155;
}

.alert-item.critical {
  border-left: 4px solid #ef4444;
}

.alert-item.warning {
  border-left: 4px solid #f59e0b;
}

.alert-item.info {
  border-left: 4px solid #3b82f6;
}

.alert-icon {
  font-size: 20px;
}

.alert-content {
  flex: 1;
}

.alert-title {
  font-weight: 600;
  margin-bottom: 4px;
}

.alert-desc {
  font-size: 12px;
  color: #64748b;
  margin-bottom: 4px;
}

.alert-time {
  font-size: 10px;
  color: #94a3b8;
}

.alert-actions {
  display: flex;
  gap: 8px;
}

.alert-btn {
  padding: 4px 8px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
}

.alert-btn.resolve {
  background: #10b981;
  color: white;
}

.empty-alerts {
