  border-bottom: 1px solid #e2e8f0;
  display: flex;
  gap: 12px;
  align-items: center;
  cursor: pointer;
  font-size: 12px;
}

.log-item:hover {
  background: #f8fafc;
}

.log-time {
  font-family: monospace;
  color: #64748b;
}

.log-level {
  padding: 2px 6px;
  border-radius: 4px;
  font-weight: 600;
  font-size: 10px;
}

.log-level.info {
  background: #dbeafe;
  color: #1e40af;
}

.log-level.warning {
  background: #fef3c7;
  color: #92400e;
}

