  font-size: 16px;
}

.chart-controls {
  display: flex;
  gap: 8px;
}

.period-btn {
  padding: 4px 12px;
  background: #f1f5f9;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
}

.dark-mode .period-btn {
  background: #334155;
  color: #e2e8f0;
}

.period-btn.active {
  background: #3b82f6;
  color: white;
}

.chart-wrapper {
  position: relative;
