methods.body:
{
      const now = Date.now();
      for (let i = 0; i < 60; i++) {
        this.cpuHistory.push({
          time: now - (60 - i) * 60000,
          value: 30 + Math.random() * 40
        });
        this.memoryHistory.push({
          time: now - (60 - i) * 60000,
          value: 40 + Math.random() * 30
