}

.alert-item {
  padding: 12px;
  border-radius: 8px;
  margin-bottom: 8px;
  display: flex;
  gap: 12px;
  background: #f8fafc;
}

.dark-mode .alert-item {
  background: #334155;
}

.alert-item.critical {
  border-left: 4px solid #ef4444;
}

.alert-item.warning {
  border-left: 4px solid #f59e0b;
}

.alert-item.info {
  border-left: 4px solid #3b82f6;
}

.alert-icon {
