  align-items: center;
  margin-bottom: 12px;
}

.service-name {
  font-weight: 600;
}

.service-status {
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 12px;
}

.service-status.healthy {
  background: #dcfce7;
  color: #166534;
}

.service-status.warning {
  background: #fef3c7;
  color: #92400e;
}

.service-status.down {
  background: #fee2e2;
  color: #991b1b;
}

