}

.metric-label {
  font-size: 11px;
  color: #64748b;
  display: block;
  margin-bottom: 4px;
}

.metric-value {
  font-weight: 600;
  font-size: 14px;
}

.service-progress {
  background: #e2e8f0;
  border-radius: 4px;
  overflow: hidden;
  height: 6px;
}

.progress-bar {
  height: 100%;
  transition: width 0.3s;
}

/* 模态框 */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
